// Merge live Companies House data (if available) back onto the sheet row,
// then compute days remaining for Confirmation Statement and Accounts.
const apiResults = $input.all();
const sheetItem = $('Split In Batches (per company)').item;
const row = sheetItem.json;
const api = apiResults[0] ? apiResults[0].json : {};

const today = new Date();
today.setHours(0,0,0,0);
const msPerDay = 1000 * 60 * 60 * 24;

function daysUntil(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  d.setHours(0,0,0,0);
  return Math.round((d - today) / msPerDay);
}

// Prefer live API dates when available, else fall back to sheet values
const csDueDate = (api.confirmation_statement && api.confirmation_statement.next_due) || row['Confirmation Statement Due'];
const accountsDueDate = (api.accounts && api.accounts.next_due) || row['Accounts Due'];

return [{
  json: {
    ...row,
    companyStatus: api.company_status || 'unknown',
    confirmationStatementDue: csDueDate,
    confirmationStatementDaysRemaining: daysUntil(csDueDate),
    accountsDue: accountsDueDate,
    accountsDaysRemaining: daysUntil(accountsDueDate)
  }
}];

const results = [];
for (const item of $input.all()) {
  const row = item.json;
  const reminders = [];

  if ([30, 14, 7, 1].includes(row.confirmationStatementDaysRemaining)) {
    reminders.push(`Confirmation Statement due ${row.confirmationStatementDue} (${row.confirmationStatementDaysRemaining} day(s) away) — must be filed within 14 days of the review period end.`);
  }
  if ([30, 14, 7, 1].includes(row.accountsDaysRemaining)) {
    reminders.push(`Annual Accounts due ${row.accountsDue} (${row.accountsDaysRemaining} day(s) away).`);
  }

  const subject = `Companies House Deadline Reminder – ${row['Company Name']} (${row['Company Number']})`;
  const body = `Hi team,\n\nThe following Companies House deadline(s) are approaching for ${row['Company Name']} (Company No. ${row['Company Number']}):\n\n` +
    reminders.map(r => `  - ${r}`).join('\n') +
    `\n\nCurrent company status per Companies House: ${row.companyStatus}.\n\nPlease action or confirm with the client as needed.\n\nKind regards,\nCompliance Tracker`;

  results.push({ json: { ...row, emailSubject: subject, emailBody: body } });
}
return results;
